/**
 * 预设卡片组件 - 基于设计规范 V2
 *
 * 设计规范:
 * - 圆角: 16dp (rounded-2xl)
 * - 背景: Zinc-800
 * - 边框: 默认 1dp zinc-700，悬停时橙色光效
 * - 阴影: 橙色阴影效果
 * - 图片高度: 根据布局动态调整
 */
@Composable
fun PresetCard(
    preset: MasterPreset,
    onClick: () -> Unit,
    onFavoriteClick: () -> Unit = {},
    onDeleteClick: () -> Unit = {},
    showFavoriteButton: Boolean = false,
    showDeleteButton: Boolean = false,
    modifier: Modifier = Modifier,
    imageHeight: Int = 200,
    showRating: Boolean = true,
    showTags: Boolean = true
) {
    val interactionSource = remember { MutableInteractionSource() }
    val isPressed by interactionSource.collectIsPressedAsState()
    val haptic = LocalHapticFeedback.current

    // 动态边框颜色 - 按下时显示橙色高亮
    val borderColor = when {
        isPressed -> HasselbladOrange.copy(alpha = 0.5f)
        else -> BorderLight
    }
    val borderWidth = if (isPressed) 1.5.dp else 1.dp

    // 阴影动画
    val shadowElevation = if (isPressed) 12.dp else 4.dp

    Card(
        modifier = modifier
            .fillMaxWidth()
            .shadow(
                elevation = shadowElevation,
                shape = RoundedCornerShape(16.dp),
                ambientColor = if (isPressed) ShadowOrangeHover else ShadowOrange,
                spotColor = if (isPressed) ShadowOrangeHover else ShadowOrange
            )
            .border(
                width = borderWidth,
                color = borderColor,
                shape = RoundedCornerShape(16.dp)
            )
            .clickable(
                interactionSource = interactionSource,
                indication = null,
                onClick = onClick
            ),
        shape = RoundedCornerShape(16.dp),
        colors = CardDefaults.cardColors(
            containerColor = Zinc800
        ),
        elevation = CardDefaults.cardElevation(
            defaultElevation = 0.dp // 使用自定义阴影
        )
    ) {
        Column {
            // 图片区域
            Box(
                modifier = Modifier
                    .fillMaxWidth()
                    .height(imageHeight.dp)
                    .clip(RoundedCornerShape(topStart = 16.dp, topEnd = 16.dp))
            ) {
                PresetImage(
                    preset = preset,
                    modifier = Modifier.fillMaxWidth()
                )

                // 左上角评分徽章
                if (showRating && preset.rating != null && preset.rating > 0) {
                    RatingBadge(
                        rating = preset.rating,
                        modifier = Modifier
                            .align(Alignment.TopStart)
                            .padding(12.dp)
                    )
                }

                // 右上角 NEW 徽章
                if (preset.isNew) {
                    NewBadge(
                        modifier = Modifier
                            .align(Alignment.TopEnd)
                            .padding(12.dp)
                    )
                }

                // 收藏按钮
                if (showFavoriteButton) {
                    IconButton(
                        onClick = {
                            haptic.perform(HapticFeedbackType.TextHandleMove)
                            onFavoriteClick()
                        },
                        modifier = Modifier
                            .align(Alignment.TopEnd)
                            .padding(
                                top = if (preset.isNew) 48.dp else 12.dp,
                                end = 12.dp
                            )
                            .size(36.dp)
                    ) {
                        Box(
                            modifier = Modifier
                                .size(32.dp)
                                .background(
                                    color = if (preset.isFavorite)
                                        HasselbladOrange.copy(alpha = 0.2f)
                                    else
                                        Color.Black.copy(alpha = 0.4f),
                                    shape = RoundedCornerShape(16.dp)
                                )
                                .border(
                                    width = 0.5.dp,
                                    color = if (preset.isFavorite)
                                        HasselbladOrange.copy(alpha = 0.5f)
                                    else
                                        Color.White.copy(alpha = 0.2f),
                                    shape = RoundedCornerShape(16.dp)
                                ),
                            contentAlignment = Alignment.Center
                        ) {
                            Icon(
                                imageVector = if (preset.isFavorite)
                                    Icons.Filled.Favorite
                                else
                                    Icons.Outlined.FavoriteBorder,
                                contentDescription = if (preset.isFavorite)
                                    stringResource(R.string.preset_favorited)
                                else
                                    stringResource(R.string.preset_favorite),
                                tint = if (preset.isFavorite)
                                    HasselbladOrange
                                else
                                    Color.White,
                                modifier = Modifier.size(18.dp)
                            )
                        }
                    }
                }

                // 删除按钮（仅自定义预设）
                if (showDeleteButton && preset.isCustom) {
                    IconButton(
                        onClick = {
                            haptic.perform(HapticFeedbackType.Confirm)
                            onDeleteClick()
                        },
                        modifier = Modifier
                            .align(Alignment.TopStart)
                            .padding(12.dp)
                            .size(36.dp)
                    ) {
                        Box(
                            modifier = Modifier
                                .size(32.dp)
                                .background(
                                    color = Color.Black.copy(alpha = 0.4f),
                                    shape = RoundedCornerShape(16.dp)
                                )
                                .border(
                                    width = 0.5.dp,
                                    color = Color.White.copy(alpha = 0.2f),
                                    shape = RoundedCornerShape(16.dp)
                                ),
                            contentAlignment = Alignment.Center
                        ) {
                            Icon(
                                imageVector = Icons.Filled.Delete,
                                contentDescription = stringResource(R.string.preset_delete),
                                tint = Color(0xFFEF4444),
                                modifier = Modifier.size(18.dp)
                            )
                        }
                    }
                }
            }

            // 内容区域
            Column(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(horizontal = 16.dp, vertical = 14.dp)
            ) {
                // 预设名称
                Text(
                    text = PresetI18n.getLocalizedPresetName(preset.name),
                    style = CardTitleStyle,
                    maxLines = 1,
                    overflow = TextOverflow.Ellipsis
                )

                Spacer(modifier = Modifier.height(6.dp))

                // 作者和设备信息
                Text(
                    text = buildString {
                        preset.author?.let { append(it) }
                        preset.deviceModel?.let {
                            if (isNotEmpty()) append(" · ")
                            append(it)
                        }
                    },
                    style = MaterialTheme.typography.bodySmall,
                    color = TextTertiary,
                    maxLines = 1,
                    overflow = TextOverflow.Ellipsis
                )

                // 标签区域
                if (showTags && !preset.tags.isNullOrEmpty()) {
                    Spacer(modifier = Modifier.height(10.dp))
                    PresetTags(tags = preset.tags.take(3))
                }

                // 参数预览（如果有）
                if (preset.iso != null || preset.shutterSpeed != null || preset.aperture != null) {
                    Spacer(modifier = Modifier.height(10.dp))
                    ParameterPreview(
                        iso = preset.iso,
                        shutterSpeed = preset.shutterSpeed,
                        aperture = preset.aperture
                    )
                }
            }
        }
    }
}

