@Composable
fun PresetCard(
    preset: MasterPreset,
    onClick: () -> Unit,
    onFavoriteClick: () -> Unit = {},
    onDeleteClick: () -> Unit = {},
    showFavoriteButton: Boolean = false,
    showDeleteButton: Boolean = false,
    modifier: Modifier = Modifier,
    imageHeight: Int = 200,
    showRating: Boolean = true,
    showTags: Boolean = true
) {
    val interactionSource = remember { MutableInteractionSource() }
    val isPressed by interactionSource.collectIsPressedAsState()
    val haptic = LocalHapticFeedback.current

    // 动态边框颜色 - 按下时显示橙色高亮
    val borderColor = when {
        isPressed -> HasselbladOrange.copy(alpha = 0.5f)
        else -> BorderLight
    }
    val borderWidth = if (isPressed) 1.5.dp else 1.dp

    // 阴影动画
    val shadowElevation = if (isPressed) 12.dp else 4.dp

    Card(
        modifier = modifier
            .fillMaxWidth()
            .shadow(
                elevation = shadowElevation,
                shape = RoundedCornerShape(16.dp),
                ambientColor = if (isPressed) ShadowOrangeHover else ShadowOrange,
                spotColor = if (isPressed) ShadowOrangeHover else ShadowOrange
            )
            .border(
                width = borderWidth,
                color = borderColor,
                shape = RoundedCornerShape(16.dp)
            )
            .clickable(
                interactionSource = interactionSource,
                indication = null,
                onClick = onClick
            ),
        shape = RoundedCornerShape(16.dp),
        colors = CardDefaults.cardColors(
            containerColor = Zinc800
        ),
        elevation = CardDefaults.cardElevation(
            defaultElevation = 0.dp // 使用自定义阴影
        )
    ) {
        Column {
            // 图片区域
            Box(
                modifier = Modifier
                    .fillMaxWidth()
                    .height(imageHeight.dp)
                    .clip(RoundedCornerShape(topStart = 16.dp, topEnd = 16.dp))
            ) {
                PresetImage(
                    preset = preset,
                    modifier = Modifier.fillMaxWidth()
                )

                // 左上角评分徽章
                if (showRating && preset.rating != null && preset.rating > 0) {
                    RatingBadge(
                        rating = preset.rating,
                        modifier = Modifier
                            .align(Alignment.TopStart)
                            .padding(12.dp)
                    )
                }

                // 右上角 NEW 徽章
                if (preset.isNew) {
                    NewBadge(
                        modifier = Modifier
                            .align(Alignment.TopEnd)
                            .padding(12.dp)
                    )
                }

                // 收藏按钮
                if (showFavoriteButton) {
                    IconButton(
                        onClick = {
                            haptic.perform(HapticFeedbackType.TextHandleMove)
                            onFavoriteClick()
                        },
                        modifier = Modifier
                            .align(Alignment.TopEnd)
                            .padding(
                                top = if (preset.isNew) 48.dp else 12.dp,
                                end = 12.dp
                            )
                            .size(36.dp)
                    ) {
                        Box(
                            modifier = Modifier
                                .size(32.dp)
                                .background(
                                    color = if (preset.isFavorite)
                                        HasselbladOrange.copy(alpha = 0.2f)
                                    else
                                        Color.Black.copy(alpha = 0.4f),
                                    shape = RoundedCornerShape(16.dp)
                                )
                                .border(
                                    width = 0.5.dp,
                                    color = if (preset.isFavorite)
                                        HasselbladOrange.copy(alpha = 0.5f)
                                    else
                                        Color.White.copy(alpha = 0.2f),
                                    shape = RoundedCornerShape(16.dp)
                                ),
                            contentAlignment = Alignment.Center
                        ) {
                            Icon(
                                imageVector = if (preset.isFavorite)
                                    Icons.Filled.Favorite
                                else
                                    Icons.Outlined.FavoriteBorder,
                                contentDescription = if (preset.isFavorite)
                                    stringResource(R.string.preset_favorited)
                                else
                                    stringResource(R.string.preset_favorite),
                                tint = if (preset.isFavorite)
                                    HasselbladOrange
                                else
                                    Color.White,
                                modifier = Modifier.size(18.dp)
                            )
                        }
                    }
                }

                // 删除按钮（仅自定义预设）
                if (showDeleteButton && preset.isCustom) {
                    IconButton(
                        onClick = {
                            haptic.perform(HapticFeedbackType.Confirm)
                            onDeleteClick()
                        },
                        modifier = Modifier
                            .align(Alignment.TopStart)
                            .padding(12.dp)
                            .size(36.dp)
                    ) {
                        Box(
                            modifier = Modifier
                                .size(32.dp)
                                .background(
                                    color = Color.Black.copy(alpha = 0.4f),
                                    shape = RoundedCornerShape(16.dp)
                                )
                                .border(
                                    width = 0.5.dp,
                                    color = Color.White.copy(alpha = 0.2f),
                                    shape = RoundedCornerShape(16.dp)
                                ),
                            contentAlignment = Alignment.Center
                        ) {
                            Icon(
                                imageVector = Icons.Filled.Delete,
                                contentDescription = stringResource(R.string.preset_delete),
                                tint = Color(0xFFEF4444),
                                modifier = Modifier.size(18.dp)
                            )
                        }
                    }
                }
            }

            // 内容区域
            Column(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(horizontal = 16.dp, vertical = 14.dp)
            ) {
                // 预设名称
                Text(
                    text = PresetI18n.getLocalizedPresetName(preset.name),
                    style = CardTitleStyle,
                    maxLines = 1,
                    overflow = TextOverflow.Ellipsis
                )

                Spacer(modifier = Modifier.height(6.dp))

                // 作者和设备信息
                Text(
                    text = buildString {
                        preset.author?.let { append(it) }
                        preset.deviceModel?.let {
                            if (isNotEmpty()) append(" · ")
                            append(it)
                        }
                    },
                    style = MaterialTheme.typography.bodySmall,
                    color = TextTertiary,
                    maxLines = 1,
                    overflow = TextOverflow.Ellipsis
                )

                // 标签区域
                if (showTags && !preset.tags.isNullOrEmpty()) {
                    Spacer(modifier = Modifier.height(10.dp))
                    PresetTags(tags = preset.tags.take(3))
                }

                // 参数预览（如果有）
                if (preset.iso != null || preset.shutterSpeed != null || preset.aperture != null) {
                    Spacer(modifier = Modifier.height(10.dp))
                    ParameterPreview(
                        iso = preset.iso,
                        shutterSpeed = preset.shutterSpeed,
                        aperture = preset.aperture
                    )
                }
            }
        }
    }
}

/**
 * 评分徽章组件
 */
@Composable
private fun RatingBadge(
    rating: Float,
    modifier: Modifier = Modifier
) {
    Box(
        modifier = modifier
            .background(
                color = Color.Black.copy(alpha = 0.6f),
                shape = RoundedCornerShape(8.dp)
            )
            .border(
                width = 0.5.dp,
                color = Color.White.copy(alpha = 0.2f),
                shape = RoundedCornerShape(8.dp)
            )
            .padding(horizontal = 8.dp, vertical = 4.dp)
    ) {
        Row(
            verticalAlignment = Alignment.CenterVertically,
            horizontalArrangement = Arrangement.spacedBy(4.dp)
        ) {
            Icon(
                imageVector = Icons.Filled.Star,
                contentDescription = null,
                tint = HasselbladOrange,
                modifier = Modifier.size(14.dp)
            )
            Text(
                text = "%.1f".format(rating),
                style = MaterialTheme.typography.labelSmall,
                color = Color.White,
                fontWeight = FontWeight.Bold
            )
        }
    }
}

/**
 * NEW 徽章组件
 */
@Composable
private fun NewBadge(
    modifier: Modifier = Modifier
) {
    Box(
        modifier = modifier
            .background(
                brush = Brush.horizontalGradient(
                    colors = listOf(GradientOrangeStart, GradientOrangeEnd)
                ),
                shape = RoundedCornerShape(6.dp)
            )
            .padding(horizontal = 10.dp, vertical = 4.dp)
    ) {
        Text(
            text = stringResource(R.string.preset_new),
            style = MaterialTheme.typography.labelSmall,
            color = Color.White,
            fontWeight = FontWeight.Bold,
            letterSpacing = 0.5.sp
        )
    }
}

/**
 * 预设标签组件
 */
@Composable
private fun PresetTags(
    tags: List<String>,
    modifier: Modifier = Modifier
) {
    Row(
        modifier = modifier.fillMaxWidth(),
        horizontalArrangement = Arrangement.spacedBy(6.dp)
    ) {
        tags.forEach { tag ->
            PresetTag(tag = tag)
        }
    }
}

/**
 * 单个标签组件
 */
@Composable
private fun PresetTag(
    tag: String,
    modifier: Modifier = Modifier
) {
    Box(
        modifier = modifier
            .background(
                color = Zinc700.copy(alpha = 0.5f),
                shape = RoundedCornerShape(6.dp)
            )
            .border(
                width = 0.5.dp,
                color = Zinc600.copy(alpha = 0.5f),
                shape = RoundedCornerShape(6.dp)
            )
            .padding(horizontal = 8.dp, vertical = 3.dp)
    ) {
        Text(
            text = tag,
            style = TagTextStyle,
            fontSize = 10.sp
        )
    }
}

/**
 * 参数预览组件
 */
@Composable
private fun ParameterPreview(
    iso: String?,
    shutterSpeed: String?,
    aperture: String?,
    modifier: Modifier = Modifier
) {
    Row(
        modifier = modifier.fillMaxWidth(),
        horizontalArrangement = Arrangement.spacedBy(12.dp)
    ) {
        iso?.let {
            ParameterItem(label = "ISO", value = it)
        }
        shutterSpeed?.let {
            ParameterItem(label = "快门", value = it)
        }
        aperture?.let {
            ParameterItem(label = "光圈", value = it)
        }
    }
}

/**
 * 参数项组件
 */
@Composable
private fun ParameterItem(
    label: String,
    value: String
) {
    Row(
        verticalAlignment = Alignment.CenterVertically,
        horizontalArrangement = Arrangement.spacedBy(3.dp)
    ) {
        Text(
            text = label,
            style = MaterialTheme.typography.labelSmall,
            color = TextTertiary,
            fontSize = 10.sp
        )
        Text(
            text = value,
            style = MaterialTheme.typography.labelSmall,
            color = TextSecondary,
            fontSize = 10.sp,
            fontWeight = FontWeight.Medium
        )
    }
}

